<?php namespace App\Models; use App\Models\Concerns\BelongsToTenant; use Illuminate\Database\Eloquent\Model; class Product extends Model {use BelongsToTenant; protected $guarded=[]; protected $casts=['colours'=>'array','sizes'=>'array','spin_images'=>'array','is_new'=>'boolean','is_active'=>'boolean','price'=>'decimal:2','compare_price'=>'decimal:2']; public function category(){return $this->belongsTo(Category::class);} public function variants(){return $this->hasMany(ProductVariant::class);} public function media(){return $this->hasMany(ProductMedia::class)->where('active',true)->where('disk','public')->orderBy('sort_order');} public function reviews(){return $this->hasMany(Review::class)->where('status','approved');} public function inventoryMovements(){return $this->hasMany(InventoryMovement::class);} }
